insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Claude Code: un agente AI per programmare', 'Che cos''è un agente AI per programmare, il ciclo capire-pianificare-agire-verificare, permessi, CLAUDE.md e buone pratiche.', 'contenuti/lezioni/claude-code.html', 'contenuti/lezioni/claude-code.pdf', now() - interval '1 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/claude-code.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il cyberspace', 'Che cos''è il cyberspace e i suoi tre livelli, fisico, logico e persona: cavi sottomarini, IXP e data center, il percorso di un pacchetto con tracert e Java, chi governa Internet e i grandi attacchi che hanno fatto la storia.', 'contenuti/lezioni/cyberspace.html', 'contenuti/lezioni/cyberspace.pdf', now() - interval '2 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/cyberspace.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La cybersecurity in azienda', 'Inventario degli asset, rischio come probabilità per impatto, registro dei rischi in Calc e in Java, i quattro trattamenti del rischio, RTO e RPO, ISO/IEC 27001, NIST CSF 2.0 e Framework Nazionale, GDPR, NIS2, ACN e le policy, anche sull''AI.', 'contenuti/lezioni/cybersecurity-aziendale.html', 'contenuti/lezioni/cybersecurity-aziendale.pdf', now() - interval '3 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/cybersecurity-aziendale.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Attaccanti: i cybercriminali', 'Profili e motivazioni degli attaccanti, white, grey e black hat, l''economia del ransomware as a service, l''ingegneria sociale con i deepfake, la Cyber Kill Chain, tattiche e tecniche di MITRE ATT&CK e i reati informatici del codice penale.', 'contenuti/lezioni/cybercriminali.html', 'contenuti/lezioni/cybercriminali.pdf', now() - interval '4 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/cybercriminali.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Difensori: i cyberdefender', 'I profili professionali ECSF, red, blue e purple team, come lavora un SOC con SIEM e SOAR, falsi positivi e falsi negativi, un mini-SIEM in Java, il triage degli allarmi, le sei fasi della risposta agli incidenti e le scadenze di notifica NIS2.', 'contenuti/lezioni/cyberdefender.html', 'contenuti/lezioni/cyberdefender.pdf', now() - interval '5 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/cyberdefender.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Network e Web App Security', 'Packet filter, firewall stateful, NGFW e WAF, DMZ e VLAN, regole del firewall della scuola, VPN e zero trust, la OWASP Top 10 del 2021, un controllo d''accesso mancante in Java, gli header di sicurezza, OWASP Juice Shop in locale e la prompt injection.', 'contenuti/lezioni/network-web-security.html', 'contenuti/lezioni/network-web-security.pdf', now() - interval '6 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/network-web-security.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cyberchallenge: Capture the Flag', 'Formati e categorie delle gare CTF, il confine tra gioco e reato, CyberChallenge.IT, OliCyber.IT e TeamItaly, codifica e cifratura, le prime flag con CyberChef, OverTheWire Bandit, picoGym e un attacco a forza bruta sul cifrario di Cesare in Java.', 'contenuti/lezioni/capture-the-flag.html', 'contenuti/lezioni/capture-the-flag.pdf', now() - interval '7 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/capture-the-flag.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'I sistemi distribuiti', 'Che cos''è un sistema distribuito secondo Tanenbaum e Lamport, vantaggi e problemi, scalabilità orizzontale e verticale, trasparenze, modelli client-server, peer-to-peer e a livelli, middleware, le otto fallacie del calcolo distribuito e il teorema CAP, con laboratori su DevTools, retry con backoff in Java e misura della latenza con curl.', 'contenuti/lezioni/sistemi-distribuiti.html', 'contenuti/lezioni/sistemi-distribuiti.pdf', now() - interval '8 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/sistemi-distribuiti.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La comunicazione con RPC', 'Remote Procedure Call da Birrell e Nelson a oggi: stub e skeleton, marshalling e ordine dei byte, chiamate sincrone e asincrone, semantiche di invocazione e idempotenza, un servizio Java RMI completo, gRPC con Protocol Buffers e JSON-RPC 2.0 come formato del Model Context Protocol.', 'contenuti/lezioni/comunicazione-rpc.html', 'contenuti/lezioni/comunicazione-rpc.pdf', now() - interval '9 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/comunicazione-rpc.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Le architetture orientate ai servizi', 'Dal monolite alla SOA e ai microservizi: servizi con contratto, accoppiamento debole, ESB, orchestrazione e coreografia, la legge di Conway, il caso Amazon e quello di Prime Video, API gateway con un laboratorio Java che instrada, autentica e risponde con i codici giusti.', 'contenuti/lezioni/architetture-soa.html', 'contenuti/lezioni/architetture-soa.pdf', now() - interval '10 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/architetture-soa.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'I web service', 'Che cos''è un web service secondo il W3C, interoperabilità tra linguaggi, XML e JSON a confronto, documenti ben formati e validi, XSD e JSON Schema, WSDL, OpenAPI e UDDI, due servizi pubblici chiamati con curl e un client Java, le API dei modelli AI come web service HTTP e JSON.', 'contenuti/lezioni/web-service.html', 'contenuti/lezioni/web-service.pdf', now() - interval '11 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/web-service.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'I web service e il protocollo HTTP', 'Anatomia di richieste e risposte HTTP/1.1, dalle origini al CERN a HTTP/3, metodi sicuri e idempotenti, codici di stato e le loro famiglie, header, assenza di stato, tipi MIME e negoziazione, osservati dal vivo con DevTools e curl e prodotti da un server Java; streaming SSE e limiti 429 nelle API di AI.', 'contenuti/lezioni/protocollo-http.html', 'contenuti/lezioni/protocollo-http.pdf', now() - interval '12 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/protocollo-http.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'I web service con SOAP', 'Storia di SOAP, struttura del messaggio con Envelope, Header, Body e Fault, WS-Security, differenze tra SOAP 1.1 e 1.2, il contratto WSDL con types, message, portType, binding e service, chiamate SOAP con curl a un servizio pubblico e a un mini server Java, pregi e limiti di SOAP.', 'contenuti/lezioni/soap-wsdl.html', 'contenuti/lezioni/soap-wsdl.pdf', now() - interval '13 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/soap-wsdl.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Web service SOAP in Java', 'Laboratorio con Maven e Jakarta XML Web Services (Metro): un servizio con @WebService pubblicato con Endpoint.publish, il WSDL generato e la corrispondenza con il codice Java, chiamate e Fault con curl, la validazione dello schema, il client generato con wsimport e una sfida a squadre.', 'contenuti/lezioni/soap-java.html', 'contenuti/lezioni/soap-java.pdf', now() - interval '14 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/soap-java.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'I web service con REST', 'Lo stile REST dalla tesi di Roy Fielding (2000): i sei vincoli, risorse e URI, rappresentazioni JSON, metodi sicuri e idempotenti, codici di stato da progettisti, modello di maturità di Richardson e HATEOAS, il progetto degli endpoint di BiblioAPI, con prove su Open-Meteo e JSONPlaceholder e le API dei modelli di AI e OpenAPI come esempi di oggi.', 'contenuti/lezioni/rest-web-service.html', 'contenuti/lezioni/rest-web-service.pdf', now() - interval '15 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/rest-web-service.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Un web service RESTful in Java', 'Laboratorio: BiblioAPI scritta con il solo JDK (com.sun.net.httpserver), con routing su metodo e percorso, JSON costruito a mano, GET, POST con 201 e Location, PUT, DELETE con 204, errori 400, 404 e 405, richieste concorrenti con ConcurrentHashMap, AtomicInteger e i thread virtuali di Java 21, e cosa controllare in un server scritto da un''AI.', 'contenuti/lezioni/rest-java.html', 'contenuti/lezioni/rest-java.pdf', now() - interval '16 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/rest-java.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Usare REST da Java e JSP', 'Laboratorio: client di BiblioAPI con java.net.http.HttpClient (GET, POST, timeout, errori di rete distinti dai codici HTTP, sendAsync) e una pagina JSP su Tomcat 10.1 che consuma l''API lato server, con l''escape dell''output contro il Cross-Site Scripting, il diagramma di sequenza browser, server web, API, e la chiamata a un modello linguistico da Java.', 'contenuti/lezioni/rest-client-jsp.html', 'contenuti/lezioni/rest-client-jsp.pdf', now() - interval '17 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/rest-client-jsp.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Testare le API con curl e Postman', 'Laboratorio: curl e la lettura dell''output verboso, collezioni con ambienti, variabili e test automatici in Postman e Bruno, catene di richieste rieseguibili, casi negativi, uno script di controllo in batch, i limiti dei test secondo Dijkstra e OpenAPI come contratto leggibile anche dagli agenti AI.', 'contenuti/lezioni/rest-curl-postman.html', 'contenuti/lezioni/rest-curl-postman.pdf', now() - interval '18 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/rest-curl-postman.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Usare REST da JavaScript', 'Laboratorio: fetch con async/await, response.ok e JSON, il meteo con Open-Meteo, una pagina che legge, aggiunge ed elimina i libri di BiblioAPI, textContent contro il Cross-Site Scripting, same-origin policy, CORS e preflight configurati sul server Java, Access-Control-Expose-Headers, e perché le chiavi delle API di AI restano sul server.', 'contenuti/lezioni/rest-javascript.html', 'contenuti/lezioni/rest-javascript.pdf', now() - interval '19 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/rest-javascript.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il ping: misurare la rete in Java', 'ICMP Echo e la storia di ping, latenza, jitter, perdita e banda, il limite della velocità della luce, InetAddress.isReachable e i suoi limiti (ICMP con privilegi, altrimenti TCP porta 7, firewall), il ping di sistema con ProcessBuilder e la difesa dalla command injection, statistiche in Java.', 'contenuti/lezioni/ping-java.html', 'contenuti/lezioni/ping-java.pdf', now() - interval '20 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/ping-java.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il ping multiplo: tutta la rete in un secondo', 'Perché un controllo sequenziale è lento, ExecutorService, Callable e Future, race condition e strumenti thread-safe, virtual thread di Java 21 misurati con isReachable e con Socket.connect, il TCP ping (refused o timeout), un monitor periodico con allarmi e CSV, scansioni etiche e legali.', 'contenuti/lezioni/ping-multiplo.html', 'contenuti/lezioni/ping-multiplo.pdf', now() - interval '21 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/ping-multiplo.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La chat con i socket TCP', 'Da Ray Tomlinson e IRC alla chat in Java: ServerSocket e Socket, il server a thread singolo e il backlog, un server multi-client con un thread per client, un protocollo di testo con NICK, MSG e QUIT, la gestione della disconnessione con finally, un client a due thread, testo in chiaro, TLS e cifratura end-to-end.', 'contenuti/lezioni/chat-socket.html', 'contenuti/lezioni/chat-socket.pdf', now() - interval '22 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/chat-socket.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'WebSocket: la chat nel browser', 'Polling, long polling, Server-Sent Events e WebSocket a confronto, l''handshake di RFC 6455 con il calcolo di Sec-WebSocket-Accept, frame, opcode e maschera, l''API WebSocket del browser, un endpoint jakarta.websocket su Tomcat 10.1, l''ispezione con DevTools e lo streaming delle risposte dei modelli di AI.', 'contenuti/lezioni/websocket-chat.html', 'contenuti/lezioni/websocket-chat.pdf', now() - interval '23 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/websocket-chat.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il mondo in tasca', 'I vincoli dei dispositivi mobili: energia in Wh e batching delle richieste, dp, sp e densità dello schermo, rete instabile e a consumo, sensori, sicurezza e frammentazione; app native, web, ibride e multipiattaforma, con laboratori in Java e DevTools e l''AI sul dispositivo.', 'contenuti/lezioni/mobile-caratteristiche.html', 'contenuti/lezioni/mobile-caratteristiche.pdf', now() - interval '24 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/mobile-caratteristiche.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il sistema operativo Android', 'L''architettura di Android (kernel Linux, HAL, ART e librerie native, framework, app), la sandbox con un utente Linux per app, i componenti, il ciclo di vita delle Activity, i permessi normali e a runtime, APK, AAB e Google Play, con un APK aperto come archivio.', 'contenuti/lezioni/android-sistema.html', 'contenuti/lezioni/android-sistema.pdf', now() - interval '25 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/android-sistema.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Kotlin per chi sa Java', 'Kotlin confrontato con Java: val e var, inferenza dei tipi e template di stringa, null safety con ?, ?., ?: e !!, funzioni con argomenti di default e when, data class, lambda sulle collezioni e trailing lambda, con laboratori nel Kotlin Playground.', 'contenuti/lezioni/kotlin-base.html', 'contenuti/lezioni/kotlin-base.pdf', now() - interval '26 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/kotlin-base.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La prima app in Android Studio', 'Nasce il progetto QuizTPSI: il modello con le View e non quello Compose, la struttura del progetto, MainActivity riga per riga, emulatore o telefono via USB, il manifest con MAIN e LAUNCHER, Gradle con minSdk e targetSdk, il ciclo di vita dal vivo in Logcat.', 'contenuti/lezioni/android-prima-app.html', 'contenuti/lezioni/android-prima-app.pdf', now() - interval '27 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/android-prima-app.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La modifica del layout: TextView e ImageView', 'La schermata della domanda di QuizTPSI: albero di View, LinearLayout e attributi di dimensione, padding e margin, risorse in strings.xml e colors.xml, ImageView con drawable e contentDescription, findViewById e View Binding, con un cenno a Jetpack Compose.', 'contenuti/lezioni/android-layout.html', 'contenuti/lezioni/android-layout.pdf', now() - interval '28 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/android-layout.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'L''interattività: Button e Toast', 'Programmazione a eventi e main thread, Button con setOnClickListener e lambda, Toast.makeText(...).show(), la logica del quiz con una data class, il bug della rotazione risolto con onSaveInstanceState, la storia di Margaret Hamilton e il tapjacking.', 'contenuti/lezioni/android-button-toast.html', 'contenuti/lezioni/android-button-toast.pdf', now() - interval '29 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/android-button-toast.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Una nuova pagina: Intent e New Activity', 'La seconda schermata di QuizTPSI: nuova Activity e manifest, Intent esplicito con putExtra e getIntExtra, chiavi in costanti, back stack e finish(), Intent impliciti per condividere e aprire il web, sicurezza delle Activity esportate e agenti AI che usano le app.', 'contenuti/lezioni/android-intent.html', 'contenuti/lezioni/android-intent.pdf', now() - interval '30 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/android-intent.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il progetto di un sito', 'Le sei fasi del progetto web, il brief con obiettivi SMART, personas e user story, requisiti funzionali e non funzionali con priorità MoSCoW, vincoli di privacy, accessibilità e diritto d''autore e la scelta motivata della tecnologia, dalla proposta del Web di Berners-Lee al repository di squadra su GitHub.', 'contenuti/lezioni/progetto-sito.html', 'contenuti/lezioni/progetto-sito.pdf', now() - interval '31 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/progetto-sito.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Mappa del sito e wireframe', 'Architettura dell''informazione, strutture gerarchica, lineare, a rete e mista, inventario dei contenuti e card sorting, mappa del sito, elementi di navigazione, wireframe mobile e desktop, mockup e prototipi, con draw.io ed Excalidraw.', 'contenuti/lezioni/mappa-sito.html', 'contenuti/lezioni/mappa-sito.pdf', now() - interval '32 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/mappa-sito.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Problematiche di web design', 'Euristiche di usabilità, layout responsive mobile first con viewport, media query, Grid e CSS moderno, colori e contrasto WCAG, tipografia leggibile, Core Web Vitals e ottimizzazione delle immagini, con DevTools in modalità dispositivo, Lighthouse e Squoosh.', 'contenuti/lezioni/web-design.html', 'contenuti/lezioni/web-design.pdf', now() - interval '33 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/web-design.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'SEO e motori di ricerca', 'Scansione, indicizzazione e ranking, PageRank, SEO on-page e off-page, robots.txt, noindex e sitemap.xml, dati strutturati JSON-LD, tecniche penalizzate e le risposte generate dall''AI nella ricerca, con Lighthouse e lo Schema Markup Validator.', 'contenuti/lezioni/seo-motori-ricerca.html', 'contenuti/lezioni/seo-motori-ricerca.pdf', now() - interval '34 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/seo-motori-ricerca.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Accessibilità web', 'Disabilità e tecnologie assistive, i principi e i livelli delle WCAG 2.2, Legge Stanca, linee guida AgID ed European Accessibility Act, HTML semantico e ARIA, test con WAVE, Lighthouse, tastiera e screen reader NVDA, e i limiti dell''AI per i testi alternativi.', 'contenuti/lezioni/accessibilita-web.html', 'contenuti/lezioni/accessibilita-web.pdf', now() - interval '35 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/accessibilita-web.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Test, pubblicazione e aggiornamento', 'Il piano di test, validatori W3C, hosting, dominio, DNS e HTTPS, pubblicazione su GitHub Pages, lettura di nslookup e curl, redirect 301 e manutenzione del sito, con la storia dell''incidente CrowdStrike del 2024 e gli agenti AI nei test automatici.', 'contenuti/lezioni/pubblicare-sito.html', 'contenuti/lezioni/pubblicare-sito.pdf', now() - interval '36 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/pubblicare-sito.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il processo di selezione', 'Le fasi per scegliere un prodotto informatico partendo dal caso Lumen Ottica: bisogni, stakeholder, requisiti funzionali e non funzionali, priorità MoSCoW, criteri di accettazione e vincoli, con laboratori in Calc e in diagrams.net.', 'contenuti/lezioni/processo-selezione.html', 'contenuti/lezioni/processo-selezione.pdf', now() - interval '37 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/processo-selezione.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il processo di ricerca', 'Dalla long list alla short list: fonti affidabili e loro rischi, test CRAAP, operatori di ricerca, RFI, RFP e RFQ, acquisti della PA con Consip e MePA, demo e proof of concept, fino alle classifiche dei modelli di AI.', 'contenuti/lezioni/ricerca-prodotti.html', 'contenuti/lezioni/ricerca-prodotti.pdf', now() - interval '38 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/ricerca-prodotti.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Valutare prodotti e fornitori', 'Criteri di valutazione di prodotto e fornitore, costo totale di possesso, licenze proprietarie, SaaS e open source, SLA con RPO e RTO, vendor lock-in e Data Act, GDPR e localizzazione dei dati, il costo per token di un''API di AI.', 'contenuti/lezioni/valutazione-fornitori.html', 'contenuti/lezioni/valutazione-fornitori.pdf', now() - interval '39 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/valutazione-fornitori.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La valutazione comparata', 'Filtro dei Must, pesi e descrittori, matrice pesata in Calc con MATR.SOMMA.PRODOTTO, analisi di sensibilità e punto di svolta, trucchi da evitare, scelta di un modello di AI open-weight o chiuso e relazione di scelta motivata.', 'contenuti/lezioni/valutazione-comparata.html', 'contenuti/lezioni/valutazione-comparata.pdf', now() - interval '40 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/valutazione-comparata.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Lo smart working', 'Il lavoro agile secondo la legge 81/2017: definizione, differenze con il telelavoro, accordo individuale, parità di trattamento, sicurezza e tutela INAIL, diritto alla disconnessione, dati dell''Osservatorio del Politecnico di Milano, sicurezza informatica da remoto e controlli tra Statuto dei lavoratori, GDPR e AI Act.', 'contenuti/lezioni/smart-working.html', 'contenuti/lezioni/smart-working.pdf', now() - interval '41 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/smart-working.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'La robotica e il mondo del lavoro', 'Robot, cobot, RPA e intelligenza artificiale; la densità di robot nel mondo con i dati IFR; che cosa dicono davvero gli studi su automazione e AI generativa (OCSE, WEF, FMI, METR); algoritmi che discriminano nella selezione; GDPR, AI Act e legge italiana sull''AI nel lavoro.', 'contenuti/lezioni/robotica-lavoro.html', 'contenuti/lezioni/robotica-lavoro.pdf', now() - interval '42 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/robotica-lavoro.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Il rapporto con la Pubblica Amministrazione', 'I diritti del Codice dell''Amministrazione Digitale, SPID e CIE a confronto, app IO e PagoPA, ANPR e autocertificazione, Fascicolo sanitario elettronico, PEC, domicilio digitale, INAD e SEND, truffe a nome della PA, il carattere di controllo del codice fiscale in Java e i dati aperti di dati.gov.it.', 'contenuti/lezioni/pa-digitale.html', 'contenuti/lezioni/pa-digitale.pdf', now() - interval '43 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/pa-digitale.html');
